"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two properties matter for every answer:

* addresses and lengths are reported at the full width the platform uses, so a
  high address or a multi-gigabyte reservation survives the trip unchanged;
* a file name is only reported when the caller can open it, which means the
  native ``\\Device\\HarddiskVolumeN\\...`` form is translated into a drive
  letter or UNC path first.
"""

import ctypes

from . import _winapi as w
from .errors import WVasError

# ``MAX_PATH`` is not enough: mapped files can carry long paths and the native
# device form is longer still.
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_UNC_DEVICES = ("\\device\\mup", "\\device\\lanmanredirector")


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: the modifier bits (``PAGE_GUARD`` and friends) are masked off and the
    remaining constant is looked up in a table.  No process is inspected.
    """
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.  Pure."""
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# process handles
# ---------------------------------------------------------------------------

def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _check_platform(pid=None):
    if not w.IS_WINDOWS:
        raise WVasError(
            "address space auditing is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )


def _process_has_exited(handle):
    code = ctypes.wintypes.DWORD(0) if False else w.wt.DWORD(0)
    if not w.GetExitCodeProcess(handle, ctypes.byref(code)):
        return False
    return code.value != w.STILL_ACTIVE


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)
    _check_platform(pid)

    denied = False
    for access in (
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_INFORMATION,
    ):
        handle = w.OpenProcess(access, False, pid)
        if handle:
            if _process_has_exited(handle):
                w.CloseHandle(handle)
                raise WVasError(
                    "no such process", kind="no-such-process", pid=pid
                )
            return handle
        error = w.last_error()
        if error == w.ERROR_ACCESS_DENIED:
            denied = True
            continue
        if error in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
            raise WVasError("no such process", kind="no-such-process", pid=pid)
        raise WVasError(
            "OpenProcess failed (error %d)" % (error,),
            kind="query-failed",
            pid=pid,
        )

    if denied:
        raise WVasError(
            "the process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    raise WVasError("OpenProcess failed", kind="query-failed", pid=pid)


# ---------------------------------------------------------------------------
# native path -> path the caller can open
# ---------------------------------------------------------------------------

def _device_map():
    """Return ``[(lowercase device name, dos prefix), ...]``.

    The map is rebuilt for every audit: drive letters come and go and a stale
    map would hand out a path that cannot be opened.
    """
    entries = []
    length = w.GetLogicalDriveStringsW(0, None)
    if not length:
        return entries
    buffer = ctypes.create_unicode_buffer(length + 1)
    written = w.GetLogicalDriveStringsW(length + 1, buffer)
    if not written:
        return entries
    raw = buffer[:written]
    target = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    for drive in raw.split("\0"):
        drive = drive.strip()
        if not drive:
            continue
        letter = drive.rstrip("\\")
        if not letter.endswith(":"):
            continue
        if not w.QueryDosDeviceW(letter, target, PATH_BUFFER_CHARS):
            continue
        device = target.value
        if not device:
            continue
        entries.append((device.rstrip("\\").lower(), letter))
    # Longest device name first so that e.g. \Device\HarddiskVolume10 is not
    # shadowed by \Device\HarddiskVolume1.
    entries.sort(key=lambda item: len(item[0]), reverse=True)
    return entries


def _strip_unc_marker(rest):
    """Turn the remainder of a redirector device path into a UNC path."""
    parts = [part for part in rest.split("\\") if part]
    # LanmanRedirector paths carry a ";Z:0000000000000000" component that
    # names the local drive letter the share is bound to; it is not part of
    # the UNC name.
    parts = [part for part in parts if not part.startswith(";")]
    if len(parts) < 2:
        return None
    return "\\\\" + "\\".join(parts)


def _dos_path(native, device_map):
    """Translate a native path into a path the caller can open.

    Accepts the ``\\Device\\...`` form returned by ``GetMappedFileNameW`` as
    well as the ``\\??\\`` / ``\\\\?\\`` prefixed forms, and returns ``None``
    when the name cannot be turned into a drive letter or UNC path.
    """
    if not native:
        return None

    path = native.replace("/", "\\")

    # \\?\ and \??\ are namespace prefixes, not part of the file name.
    for prefix in ("\\\\?\\", "\\??\\"):
        if path.lower().startswith(prefix.lower()):
            path = path[len(prefix):]
            if path[:4].lower() == "unc\\":
                path = "\\\\" + path[4:]
            break

    lowered = path.lower()

    if lowered.startswith("\\device\\"):
        for device, letter in device_map:
            if lowered.startswith(device) and (
                len(lowered) == len(device) or lowered[len(device)] == "\\"
            ):
                return letter + path[len(device):]
        for device in _UNC_DEVICES:
            if lowered.startswith(device) and (
                len(lowered) == len(device) or lowered[len(device)] == "\\"
            ):
                return _strip_unc_marker(path[len(device):])
        return None

    if path.startswith("\\\\"):
        # already a UNC path
        return path if len(path.strip("\\")) else None

    if len(path) >= 3 and path[1] == ":" and path[2] == "\\" and path[0].isalpha():
        return path

    return None


def _mapped_path(handle, address, device_map):
    """Return the openable path of the file backing ``address``, else ``None``."""
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        # Anonymous mappings, private memory and reserved ranges have no file
        # behind them at all.
        return None
    return _dos_path(buffer.value, device_map)


def _module_path(handle, address, device_map):
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return _dos_path(buffer.value, device_map)


# ---------------------------------------------------------------------------
# the audit itself
# ---------------------------------------------------------------------------

def _walk(handle, pid, include_reserved, device_map):
    result = []
    mbi = w.MEMORY_BASIC_INFORMATION()
    size_of_mbi = ctypes.sizeof(mbi)
    address = 0
    first = True

    while address <= w.MAX_USER_ADDRESS:
        returned = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size_of_mbi
        )
        if not returned:
            error = w.last_error()
            if first:
                if error == w.ERROR_ACCESS_DENIED:
                    raise WVasError(
                        "the process cannot be queried",
                        kind="access-denied",
                        pid=pid,
                    )
                if error not in (w.ERROR_INVALID_PARAMETER, w.ERROR_SUCCESS):
                    raise WVasError(
                        "VirtualQueryEx failed (error %d)" % (error,),
                        kind="query-failed",
                        pid=pid,
                    )
            # The walk has run past the end of the user address space.
            break
        first = False

        # ``BaseAddress`` and ``RegionSize`` are pointer sized; reporting them
        # unmasked is what keeps high addresses and >4 GiB ranges truthful.
        base = mbi.BaseAddress or 0
        size = mbi.RegionSize or 0
        state = mbi.State

        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            if state == w.MEM_COMMIT:
                path = _mapped_path(handle, base, device_map)
            else:
                # Nothing is mapped into a reserved range, so there is no file
                # behind it.
                path = None
            result.append({
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(mbi.Type),
                "protect": protection_name(mbi.Protect),
                "path": path,
                "image": mbi.Type == w.MEM_IMAGE,
            })

        next_address = base + size
        if next_address <= address:
            break
        address = next_address

    result.sort(key=lambda item: item["base"])
    return result


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``.  With ``include_reserved`` the reserved
    but uncommitted ranges are reported next to the committed ones; without it
    only committed ranges are reported.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        return _walk(handle, pid, bool(include_reserved), device_map)
    except WVasError:
        raise
    except OSError as exc:
        raise WVasError(
            "the address space query failed: %s" % (exc,),
            kind="query-failed",
            pid=pid,
        ) from exc
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them, in audit order."""
    return [item for item in regions(pid) if item["path"] is not None]


def _enumerate_modules(handle, pid):
    """Return the base addresses of the loaded images, or ``None`` on failure."""
    count = 256
    while True:
        array = (ctypes.c_void_p * count)()
        needed = w.wt.DWORD(0)
        if w.EnumProcessModulesEx is not None:
            ok = w.EnumProcessModulesEx(
                handle,
                ctypes.byref(array),
                ctypes.sizeof(array),
                ctypes.byref(needed),
                w.LIST_MODULES_ALL,
            )
        else:  # pragma: no cover - only on platforms without the Ex variant
            ok = w.EnumProcessModules(
                handle,
                ctypes.byref(array),
                ctypes.sizeof(array),
                ctypes.byref(needed),
            )
        if not ok:
            return None
        pointer_size = ctypes.sizeof(ctypes.c_void_p)
        available = needed.value // pointer_size
        if available > count:
            count = available + 16
            continue
        return [array[index] or 0 for index in range(available)]


def _modules_from_enumeration(handle, pid, device_map):
    bases = _enumerate_modules(handle, pid)
    if bases is None:
        return None
    found = []
    for base in bases:
        info = w.MODULEINFO()
        if w.GetModuleInformation(
            handle, ctypes.c_void_p(base), ctypes.byref(info), ctypes.sizeof(info)
        ):
            size = info.SizeOfImage
            base = info.lpBaseOfDll or base
        else:
            size = 0
        path = _module_path(handle, base, device_map)
        if path is None:
            path = _mapped_path(handle, base, device_map)
        found.append({"path": path, "base": base, "size": size})
    return found


def _modules_from_regions(handle, pid, device_map):
    """Fall back to grouping the image regions by their allocation base."""
    found = {}
    mbi = w.MEMORY_BASIC_INFORMATION()
    size_of_mbi = ctypes.sizeof(mbi)
    address = 0
    while address <= w.MAX_USER_ADDRESS:
        if not w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size_of_mbi
        ):
            break
        base = mbi.BaseAddress or 0
        size = mbi.RegionSize or 0
        if mbi.Type == w.MEM_IMAGE and mbi.State != w.MEM_FREE:
            allocation_base = mbi.AllocationBase or base
            entry = found.get(allocation_base)
            end = base + size
            if entry is None:
                path = _module_path(handle, allocation_base, device_map)
                if path is None:
                    path = _mapped_path(handle, base, device_map)
                found[allocation_base] = {
                    "path": path,
                    "base": allocation_base,
                    "size": end - allocation_base,
                }
            else:
                entry["size"] = max(entry["size"], end - allocation_base)
                if entry["path"] is None:
                    entry["path"] = _mapped_path(handle, base, device_map)
        next_address = base + size
        if next_address <= address:
            break
        address = next_address
    return list(found.values())


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is reported twice.  An
    image whose file name cannot be turned into an openable path is still
    listed, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        found = _modules_from_enumeration(handle, pid, device_map)
        if not found:
            found = _modules_from_regions(handle, pid, device_map)
    except WVasError:
        raise
    except OSError as exc:
        raise WVasError(
            "the module query failed: %s" % (exc,),
            kind="query-failed",
            pid=pid,
        ) from exc
    finally:
        w.CloseHandle(handle)

    unique = []
    seen_bases = set()
    seen_paths = set()
    for item in sorted(found, key=lambda entry: entry["base"]):
        if item["base"] in seen_bases:
            continue
        if item["path"] is not None:
            key = item["path"].lower()
            if key in seen_paths:
                continue
            seen_paths.add(key)
        seen_bases.add(item["base"])
        unique.append({
            "path": item["path"],
            "base": item["base"],
            "size": item["size"],
        })
    return unique

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two properties matter for every answer:

* addresses and lengths are reported at the full width the platform uses, so a
  high address or a multi-gigabyte range survives the trip unchanged;
* a file name is only reported when the caller can open it, which means the
  native ``\\Device\\HarddiskVolumeN\\...`` form is translated into a drive
  letter or UNC path first, and anything that cannot be translated is reported
  as ``None`` rather than as a name nobody can use.
"""

import ctypes
import ctypes.wintypes as wintypes

from . import _winapi as w
from .errors import WVasError

# ``MAX_PATH`` is not enough: mapped files can carry long paths and the native
# device form is longer still.
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

# Network redirector devices: the remainder of the path is a UNC name.
_UNC_DEVICES = ("\\device\\mup", "\\device\\lanmanredirector")


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: the modifier bits (``PAGE_GUARD`` and friends) are masked off and the
    remaining constant is looked up in a table.  No process is inspected.
    """
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.  Pure."""
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# process handles
# ---------------------------------------------------------------------------

def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _check_platform(pid=None):
    if not w.IS_WINDOWS:
        raise WVasError(
            "address space auditing is only supported on Windows",
            kind="unsupported",
            pid=pid,
        )


def _process_has_exited(handle):
    """True when the handle refers to a process that is no longer running."""
    code = wintypes.DWORD(0)
    if not w.GetExitCodeProcess(handle, ctypes.byref(code)):
        return False
    return code.value != w.STILL_ACTIVE


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)
    _check_platform(pid)

    denied = False
    for access in (
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_LIMITED_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_INFORMATION,
        w.PROCESS_QUERY_LIMITED_INFORMATION,
    ):
        handle = w.OpenProcess(access, False, pid)
        if handle:
            if _process_has_exited(handle):
                w.CloseHandle(handle)
                raise WVasError("no such process", kind="no-such-process", pid=pid)
            return handle

        error = w.last_error()
        if error == w.ERROR_ACCESS_DENIED:
            # The process exists, only this access mask was refused; a weaker
            # mask may still be enough to answer the question.
            denied = True
            continue
        if error in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
            raise WVasError("no such process", kind="no-such-process", pid=pid)
        raise WVasError(
            "OpenProcess failed (error %d)" % (error,),
            kind="query-failed",
            pid=pid,
        )

    if denied:
        raise WVasError(
            "the process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    raise WVasError("OpenProcess failed", kind="query-failed", pid=pid)


def _classify_failure(handle, pid, error, what):
    """Turn a Win32 error on an opened process into a :class:`WVasError`."""
    if _process_has_exited(handle):
        return WVasError("no such process", kind="no-such-process", pid=pid)
    if error in (w.ERROR_ACCESS_DENIED, w.ERROR_PARTIAL_COPY):
        return WVasError(
            "the process cannot be queried", kind="access-denied", pid=pid
        )
    return WVasError(
        "%s failed (error %d)" % (what, error), kind="query-failed", pid=pid
    )


# ---------------------------------------------------------------------------
# native path -> path the caller can open
# ---------------------------------------------------------------------------

def _device_map():
    """Return ``[(lowercase device name, dos prefix), ...]``.

    The map is rebuilt for every audit: drive letters come and go and a stale
    map would hand out a path that cannot be opened.
    """
    entries = []
    length = w.GetLogicalDriveStringsW(0, None)
    if not length:
        return entries
    buffer = ctypes.create_unicode_buffer(length + 1)
    written = w.GetLogicalDriveStringsW(length + 1, buffer)
    if not written:
        return entries

    raw = buffer[:written]
    target = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    for drive in raw.split("\0"):
        drive = drive.strip()
        if not drive:
            continue
        letter = drive.rstrip("\\")
        if not letter.endswith(":"):
            continue
        if not w.QueryDosDeviceW(letter, target, PATH_BUFFER_CHARS):
            continue
        device = target.value
        if not device:
            continue
        entries.append((device.rstrip("\\").lower(), letter))

    # Longest device name first, so that \Device\HarddiskVolume10 is not
    # shadowed by \Device\HarddiskVolume1.
    entries.sort(key=lambda item: len(item[0]), reverse=True)
    return entries


def _unc_from_redirector(rest):
    """Turn the remainder of a redirector device path into a UNC path."""
    parts = [part for part in rest.split("\\") if part]
    # LanmanRedirector paths carry a ";Z:0000000000000000" component naming
    # the local drive letter the share is bound to; it is not part of the name.
    parts = [part for part in parts if not part.startswith(";")]
    if len(parts) < 2:
        return None
    return "\\\\" + "\\".join(parts)


def _dos_path(native, device_map):
    """Translate a native path into a path the caller can open.

    Accepts the ``\\Device\\...`` form returned by ``GetMappedFileNameW`` as
    well as the ``\\??\\`` and ``\\\\?\\`` prefixed forms, and returns ``None``
    when the name cannot be turned into a drive letter or UNC path.
    """
    if not native:
        return None

    path = native.replace("/", "\\")

    # \\?\ and \??\ are namespace prefixes, not part of the file name.
    for prefix in ("\\\\?\\", "\\??\\"):
        if path[:len(prefix)].lower() == prefix.lower():
            path = path[len(prefix):]
            if path[:4].lower() == "unc\\":
                path = "\\\\" + path[4:]
            break

    lowered = path.lower()

    if lowered.startswith("\\device\\"):
        for device, letter in device_map:
            if lowered.startswith(device) and (
                len(lowered) == len(device) or lowered[len(device)] == "\\"
            ):
                rest = path[len(device):]
                return letter + (rest if rest else "\\")
        for device in _UNC_DEVICES:
            if lowered.startswith(device) and (
                len(lowered) == len(device) or lowered[len(device)] == "\\"
            ):
                return _unc_from_redirector(path[len(device):])
        # A device with neither a drive letter nor a share behind it: there is
        # no name the caller could open.
        return None

    if path.startswith("\\\\"):
        # Already a UNC path.
        return path if path.strip("\\") else None

    if len(path) >= 3 and path[0].isalpha() and path[1] == ":" and path[2] == "\\":
        return path

    return None


def _mapped_path(handle, address, device_map):
    """Return the openable path of the file backing ``address``, else ``None``."""
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        # Anonymous mappings, private memory and reserved ranges have no file
        # behind them at all - that is reported as ``None``, never as "".
        return None
    return _dos_path(buffer.value, device_map)


def _module_path(handle, address, device_map):
    """Return the openable path of the image loaded at ``address``."""
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(
        handle, ctypes.c_void_p(address), buffer, PATH_BUFFER_CHARS
    )
    if not written:
        return None
    return _dos_path(buffer.value, device_map)


# ---------------------------------------------------------------------------
# the audit itself
# ---------------------------------------------------------------------------

def _walk(handle, pid, include_reserved, device_map):
    result = []
    mbi = w.MEMORY_BASIC_INFORMATION()
    size_of_mbi = ctypes.sizeof(mbi)
    address = 0
    first = True

    while address <= w.MAX_USER_ADDRESS:
        returned = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size_of_mbi
        )
        if not returned:
            if first:
                # Not a single region could be read: that is a failure, not an
                # empty address space.
                raise _classify_failure(
                    handle, pid, w.last_error(), "VirtualQueryEx"
                )
            # The walk has reached the end of the user address space.
            break
        first = False

        # ``BaseAddress`` and ``RegionSize`` are pointer sized; reporting them
        # unmasked is what keeps high addresses and ranges beyond 4 GiB
        # truthful.
        base = mbi.BaseAddress or 0
        size = mbi.RegionSize or 0
        state = mbi.State

        if state == w.MEM_COMMIT or (include_reserved and state == w.MEM_RESERVE):
            if state == w.MEM_COMMIT:
                path = _mapped_path(handle, base, device_map)
            else:
                # Nothing is mapped into a reserved range, so no file backs it.
                path = None
            result.append({
                "base": base,
                "size": size,
                "state": "commit" if state == w.MEM_COMMIT else "reserve",
                "type": type_name(mbi.Type),
                "protect": protection_name(mbi.Protect),
                "path": path,
                "image": mbi.Type == w.MEM_IMAGE,
            })

        next_address = base + size
        if next_address <= address:
            break
        address = next_address

    result.sort(key=lambda item: item["base"])
    return result


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``.  With ``include_reserved`` the reserved
    but uncommitted ranges are reported next to the committed ones; without it
    only committed ranges are reported.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        return _walk(handle, pid, bool(include_reserved), device_map)
    except WVasError:
        raise
    except OSError as exc:
        raise WVasError(
            "the address space query failed: %s" % (exc,),
            kind="query-failed",
            pid=pid,
        ) from exc
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them, in audit order."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# modules
# ---------------------------------------------------------------------------

def _enumerate_modules(handle):
    """Return ``(bases, error)``; ``bases`` is ``None`` when enumeration failed."""
    count = 256
    while True:
        array = (ctypes.c_void_p * count)()
        needed = wintypes.DWORD(0)
        if w.EnumProcessModulesEx is not None:
            ok = w.EnumProcessModulesEx(
                handle,
                ctypes.byref(array),
                ctypes.sizeof(array),
                ctypes.byref(needed),
                w.LIST_MODULES_ALL,
            )
        else:  # pragma: no cover - only on platforms without the Ex variant
            ok = w.EnumProcessModules(
                handle,
                ctypes.byref(array),
                ctypes.sizeof(array),
                ctypes.byref(needed),
            )
        if not ok:
            return None, w.last_error()
        pointer_size = ctypes.sizeof(ctypes.c_void_p)
        available = needed.value // pointer_size
        if available > count:
            # The module list grew between the two calls; retry with room to
            # spare so that no image is dropped from the report.
            count = available + 16
            continue
        return [array[index] or 0 for index in range(available)], w.ERROR_SUCCESS


def _modules_from_enumeration(handle, device_map):
    bases, error = _enumerate_modules(handle)
    if bases is None:
        return None, error
    found = []
    for base in bases:
        info = w.MODULEINFO()
        if w.GetModuleInformation(
            handle, ctypes.c_void_p(base), ctypes.byref(info), ctypes.sizeof(info)
        ):
            size = info.SizeOfImage
            base = info.lpBaseOfDll or base
        else:
            size = 0
        # An image whose name cannot be resolved still belongs in the report.
        path = _module_path(handle, base, device_map)
        if path is None:
            path = _mapped_path(handle, base, device_map)
        found.append({"path": path, "base": base, "size": size})
    return found, w.ERROR_SUCCESS


def _modules_from_regions(handle, device_map):
    """Fall back to grouping the image regions by their allocation base.

    Every image occupies several regions (headers, text, data, ...); keying on
    the allocation base is what reports one entry per loaded image instead of
    one entry per section.
    """
    found = {}
    mbi = w.MEMORY_BASIC_INFORMATION()
    size_of_mbi = ctypes.sizeof(mbi)
    address = 0
    while address <= w.MAX_USER_ADDRESS:
        if not w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size_of_mbi
        ):
            break
        base = mbi.BaseAddress or 0
        size = mbi.RegionSize or 0
        if mbi.Type == w.MEM_IMAGE and mbi.State != w.MEM_FREE:
            allocation_base = mbi.AllocationBase or base
            end = base + size
            entry = found.get(allocation_base)
            if entry is None:
                path = _module_path(handle, allocation_base, device_map)
                if path is None:
                    path = _mapped_path(handle, base, device_map)
                found[allocation_base] = {
                    "path": path,
                    "base": allocation_base,
                    "size": end - allocation_base,
                }
            else:
                entry["size"] = max(entry["size"], end - allocation_base)
                if entry["path"] is None:
                    entry["path"] = _mapped_path(handle, base, device_map)
        next_address = base + size
        if next_address <= address:
            break
        address = next_address
    return list(found.values())


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is reported twice.  An
    image whose file name cannot be turned into an openable path is still
    listed, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        found, error = _modules_from_enumeration(handle, device_map)
        if not found:
            # Either the enumeration failed outright or it came back empty;
            # the image regions of the address space still describe the images.
            from_regions = _modules_from_regions(handle, device_map)
            if not from_regions and found is None:
                raise _classify_failure(
                    handle, pid, error, "EnumProcessModulesEx"
                )
            found = from_regions
    except WVasError:
        raise
    except OSError as exc:
        raise WVasError(
            "the module query failed: %s" % (exc,),
            kind="query-failed",
            pid=pid,
        ) from exc
    finally:
        w.CloseHandle(handle)

    unique = []
    seen_bases = set()
    seen_paths = set()
    for item in sorted(found, key=lambda entry: entry["base"]):
        if item["base"] in seen_bases:
            continue
        if item["path"] is not None:
            key = item["path"].lower()
            if key in seen_paths:
                continue
            seen_paths.add(key)
        seen_bases.add(item["base"])
        unique.append({
            "path": item["path"],
            "base": item["base"],
            "size": item["size"],
        })
    return unique
